#!/bin/sh
# @domain: policies
# #4963 — a git tree in $1 holding one violation of policy-arch-three-generator-separation; the check run there must count it.
set -e
cd "$1"
git init -q .
mkdir -p directing/products/zz/api
printf '# Generated by athena-gen (#4490) — DO NOT EDIT\n[package]\nname = "zz-api"\n' > directing/products/zz/api/Cargo.toml
git add -A
